/*
Shader animado en GLSL para Shadertoy:
Julia fractal con colores neon y fondo dinámico que cambia constantemente.
*/

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalización de coordenadas: el centro de la pantalla es (0,0)
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;

    // Aplicamos rotación, desplazamiento y zoom para animar la vista
    float angle = iTime * 0.3;
    mat2 rot = mat2(cos(angle), -sin(angle),
                    sin(angle),  cos(angle));
    uv = rot * uv;
    uv += 0.2 * vec2(sin(iTime * 0.5), cos(iTime * 0.5));
    float zoom = 1.0 + 0.3 * sin(iTime * 0.5);
    uv *= zoom;


    vec3 bgColor = 0.3 + 0.5 * cos(iTime * 0.9 + vec3(0.3, 0.3, 0.7));

    // Parámetro 'c' animado para la Julia set: hace variar la forma del fractal
    vec2 c = vec2(0.7885 * cos(iTime * 0.4),
                  0.7885 * sin(iTime * 0.4));

    // Iteración de la Julia set
    vec2 z = uv;
    int maxIterations = 300;
    int iter;
    for (iter = 0; iter < maxIterations; iter++) {
        vec2 z_new = vec2(z.x*z.x - z.y*z.y, 2.0*z.x*z.y) + c;
        if(dot(z_new, z_new) > 4.0) break;
        z = z_new;
    }

    // Suavizado del conteo de iteraciones para evitar bandas abruptas
    float normIter = float(iter);
    if(iter < maxIterations) {
        float log_zn = log(dot(z, z)) * 0.5;
        float nu = log(log_zn / log(2.0)) / log(2.0);
        normIter = normIter + 1.0 - nu;
    }
    normIter /= float(maxIterations);

    // Paleta neon vibrante para el fractal
    vec3 baseColor = 0.5 + 0.5 * cos(6.2831 * normIter * 1.2 + vec3(0.2, 0.7, 1.3));

    // En zonas donde normIter se acerca a 1 (lo que suele dar lugar a áreas poco coloreadas)
    // se mezcla el color del fractal con el fondo dinámico.
    float mixFactor = smoothstep(0.85, 0.6, normIter);
    vec3 color = mix(baseColor, bgColor, mixFactor);

    // Se añade un efecto glow para resaltar los detalles neon
    float glow = exp(-8.0 * normIter);
    color += glow * vec3(0.8, 0.3, 0.9);

    fragColor = vec4(color, 1.0);
}
